{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "სავარძლის ქვეშ მდებარე ყვითელი ღილაკი ფოტოზე დაფარულია და parts სიაში არ არის; მისი ID ვერ მიეთითება. რეგულირების შემდეგ დარწმუნდი, რომ მექანიზმი დაფიქსირდა."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": [],
      "warn": "წონის ასარჩევი ყვითელი ქინძისთავი და ფილები ფოტოზე არ ჩანს და parts სიაში არ არის. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები უძრავია და ჩამოშვებულია."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოხრილი ზედა სახელური", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p1", "p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "მარჯვენა მუხლის ბალიში", "tone": "brand"},
        {"part": "p3", "label": "მარცხენა მუხლის ბალიში", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "სავარძელი ფოტოზე დაფარულია და მისთვის ID მინიჭებული არ არის; მონიშნულია მხოლოდ სახელური და ორივე ხილული ბალიში."
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "სახელური", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "down"},
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "იმოძრავე კონტროლირებულად, მოქაჩვისა და ტანის ქანაობის გარეშე; სახელური კისრის უკან არ ჩამოწიო."
    }
  ],
  "unknown_parts": [
    "სავარძლის სიმაღლის მარეგულირებელი ყვითელი ღილაკი",
    "წონის ასარჩევი ყვითელი ქინძისთავი და წონის ფილები",
    "სავარძელი"
  ]
}
